   193  PJ *PROJECTION(geos) {
   194      struct pj_opaque *Q = pj_calloc (1, sizeof (struct pj_opaque));
   195      if (0==Q)
   196          return pj_default_destructor (P, ENOMEM);
   197      P->opaque = Q;
   198
   199      if ((Q->h = pj_param(P->ctx, P->params, "dh").f) <= 0.)
   200          pj_default_destructor (P, PJD_ERR_H_LESS_THAN_ZERO);
   201
   202      if (P->phi0 != 0.0)
   203          pj_default_destructor (P, PJD_ERR_UNKNOWN_PRIME_MERIDIAN);
   204
   205      Q->sweep_axis = pj_param(P->ctx, P->params, "ssweep").s;
   206      if (Q->sweep_axis == NULL)
   207        Q->flip_axis = 0;
   208      else {
   209          if (Q->sweep_axis[1] != '\0' || (Q->sweep_axis[0] != 'x' && Q->sweep_axis[0] != 'y'))
   210              pj_default_destructor (P, PJD_ERR_INVALID_SWEEP_AXIS);
   211
   212          if (Q->sweep_axis[0] == 'x')
   213            Q->flip_axis = 1;
   214          else
   215            Q->flip_axis = 0;
   216      }
   217
   218      Q->radius_g_1 = Q->h / P->a;
   219      Q->radius_g = 1. + Q->radius_g_1;
   220      Q->C  = Q->radius_g * Q->radius_g - 1.0;
   221      if (P->es != 0.0) {
   222          Q->radius_p      = sqrt (P->one_es);
   223          Q->radius_p2     = P->one_es;
   224          Q->radius_p_inv2 = P->rone_es;
   225          P->inv = e_inverse;
   226          P->fwd = e_forward;
   227      } else {
   228          Q->radius_p = Q->radius_p2 = Q->radius_p_inv2 = 1.0;
   229          P->inv = s_inverse;
   230          P->fwd = s_forward;
   231      }
   232
   233      return P;
   234  }
