    85  /**********************************************************************/
    86  void *pj_calloc (size_t n, size_t size) {
    87  /***********************************************************************
    88  pj_calloc is the pj-equivalent of calloc().
    89
    90  It allocates space for an array of <n> elements of size <size>.
    91  The array is initialized to zeros.
    92  ***********************************************************************/
    93      void *res = pj_malloc (n*size);
    94      if (0==res)
    95          return 0;
    96      memset (res, 0, n*size);
    97      return res;
    98  }
