   141      Also called from pj_init_ctx when encountering errors before the PJ
   142      proper is allocated.
   143  ******************************************************************************/
   144      paralist *t, *n;
   145      for (t = start; t; t = n) {
   146          n = t->next;
   147          pj_dealloc(t);
   148      }
